public class Solution {
    // SPEC: count elements strictly greater than the first element
    public static int countAboveFirst(int[] arr) {
        int count = 0;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > arr[0]) {
                count--;
            }
        }
        return count;
    }
}
